
CREATE DATABASE StockTradingPlatform;
GO

USE StockTradingPlatform;
GO

CREATE TABLE Users
(
user_id INT PRIMARY KEY,
username VARCHAR(50),
first_name VARCHAR(50),
last_name VARCHAR(50),
email VARCHAR(100),
phone VARCHAR(15),
date_of_birth DATE,
gender VARCHAR(10),
address VARCHAR(100),
city VARCHAR(50),
state VARCHAR(50),
country VARCHAR(50),
registration_date DATE,
account_status VARCHAR(20),
pan_number VARCHAR(20),
occupation VARCHAR(50),
annual_income DECIMAL(12,2),
risk_level VARCHAR(20),
login_count INT,
last_login DATE
);
GO

CREATE TABLE Accounts
(
account_id INT PRIMARY KEY,
user_id INT,
account_number VARCHAR(30),
account_type VARCHAR(30),
balance DECIMAL(15,2),
available_balance DECIMAL(15,2),
margin_balance DECIMAL(15,2),
currency VARCHAR(10),
account_status VARCHAR(20),
opened_date DATE,
last_transaction_date DATE,
tax_status VARCHAR(30),
risk_level VARCHAR(20),
bank_name VARCHAR(100),
ifsc_code VARCHAR(20),
nominee_name VARCHAR(100),
branch VARCHAR(50),
city VARCHAR(50),
trading_enabled BIT,
created_date DATE,
FOREIGN KEY (user_id) REFERENCES Users(user_id)
);
GO

CREATE TABLE KYC
(
kyc_id INT PRIMARY KEY,
user_id INT,
account_id INT,
document_type VARCHAR(30),
document_number VARCHAR(30),
verification_status VARCHAR(20),
verification_date DATE,
full_name VARCHAR(100),
date_of_birth DATE,
gender VARCHAR(10),
address VARCHAR(100),
city VARCHAR(50),
state VARCHAR(50),
country VARCHAR(50),
pincode VARCHAR(10),
pan_number VARCHAR(20),
aadhaar_last4 VARCHAR(10),
occupation VARCHAR(50),
submitted_date DATE,
remarks VARCHAR(100),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id)
);
GO

CREATE TABLE Brokers
(
broker_id INT PRIMARY KEY,
broker_name VARCHAR(100),
license_number VARCHAR(30),
contact_person VARCHAR(100),
email VARCHAR(100),
phone VARCHAR(15),
website VARCHAR(150),
address VARCHAR(100),
city VARCHAR(50),
state VARCHAR(50),
country VARCHAR(50),
commission_rate DECIMAL(5,2),
status VARCHAR(20),
license_expiry DATE,
registration_date DATE,
support_email VARCHAR(100),
support_phone VARCHAR(15),
account_type VARCHAR(30),
trading_platform VARCHAR(50),
remarks VARCHAR(100)
);
GO

CREATE TABLE Market_Sectors
(
sector_id INT PRIMARY KEY,
sector_name VARCHAR(100),
sector_code VARCHAR(20),
description VARCHAR(150),
industry_group VARCHAR(100),
market_type VARCHAR(30),
risk_level VARCHAR(20),
average_growth DECIMAL(7,2),
created_date DATE,
status VARCHAR(20),
country VARCHAR(50),
currency VARCHAR(10),
regulatory_body VARCHAR(100),
headquarters VARCHAR(50),
employee_range VARCHAR(30),
website VARCHAR(150),
listed_companies INT,
top_company VARCHAR(100),
manager_name VARCHAR(100),
remarks VARCHAR(100)
);
GO

CREATE TABLE Companies
(
company_id INT PRIMARY KEY,
sector_id INT,
company_name VARCHAR(150),
short_name VARCHAR(50),
symbol VARCHAR(30),
registration_number VARCHAR(30),
company_type VARCHAR(50),
founded_date DATE,
headquarters VARCHAR(100),
city VARCHAR(50),
state VARCHAR(50),
country VARCHAR(50),
website VARCHAR(150),
market_cap DECIMAL(20,2),
employees INT,
status VARCHAR(20),
listing_date DATE,
face_value DECIMAL(10,2),
industry_rank INT,
description VARCHAR(150),
FOREIGN KEY (sector_id) REFERENCES Market_Sectors(sector_id)
);
GO

CREATE TABLE Exchanges
(
exchange_id INT PRIMARY KEY,
exchange_name VARCHAR(100),
exchange_code VARCHAR(20),
country VARCHAR(50),
city VARCHAR(50),
currency VARCHAR(10),
timezone VARCHAR(30),
opening_time TIME,
closing_time TIME,
website VARCHAR(150),
established_date DATE,
regulatory_authority VARCHAR(100),
contact_email VARCHAR(100),
contact_phone VARCHAR(20),
status VARCHAR(20),
market_type VARCHAR(30),
trading_days VARCHAR(50),
clearing_house VARCHAR(100),
index_name VARCHAR(50),
remarks VARCHAR(100)
);
GO

CREATE TABLE Stocks
(
stock_id INT PRIMARY KEY,
company_id INT,
exchange_id INT,
sector_id INT,
symbol VARCHAR(30),
stock_name VARCHAR(150),
stock_type VARCHAR(30),
market_price DECIMAL(15,2),
opening_price DECIMAL(15,2),
closing_price DECIMAL(15,2),
day_high DECIMAL(15,2),
day_low DECIMAL(15,2),
market_cap DECIMAL(20,2),
volume INT,
listing_date DATE,
currency VARCHAR(10),
status VARCHAR(20),
face_value DECIMAL(10,2),
lot_size INT,
remarks VARCHAR(100),
FOREIGN KEY (company_id) REFERENCES Companies(company_id),
FOREIGN KEY (exchange_id) REFERENCES Exchanges(exchange_id),
FOREIGN KEY (sector_id) REFERENCES Market_Sectors(sector_id)
);
GO

CREATE TABLE Stock_Price_History
(
history_id INT PRIMARY KEY,
stock_id INT,
company_id INT,
trade_date DATE,
open_price DECIMAL(15,2),
high_price DECIMAL(15,2),
low_price DECIMAL(15,2),
close_price DECIMAL(15,2),
adjusted_close DECIMAL(15,2),
volume INT,
previous_close DECIMAL(15,2),
price_change DECIMAL(15,2),
percentage_change DECIMAL(7,2),
market_status VARCHAR(20),
currency VARCHAR(10),
data_source VARCHAR(100),
exchange_code VARCHAR(20),
sector_name VARCHAR(100),
company_name VARCHAR(150),
remarks VARCHAR(100),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id)
);
GO

CREATE TABLE Orders
(
order_id INT PRIMARY KEY,
account_id INT,
user_id INT,
stock_id INT,
company_id INT,
order_type VARCHAR(10),
order_category VARCHAR(30),
quantity INT,
price DECIMAL(15,2),
stop_price DECIMAL(15,2),
total_amount DECIMAL(15,2),
commission DECIMAL(10,2),
tax DECIMAL(10,2),
order_status VARCHAR(20),
order_date DATE,
expiry_date DATE,
broker_id INT,
exchange_code VARCHAR(20),
payment_method VARCHAR(30),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id)
);
GO

CREATE TABLE Trades
(
trade_id INT PRIMARY KEY,
order_id INT,
account_id INT,
user_id INT,
stock_id INT,
company_id INT,
trade_type VARCHAR(10),
trade_price DECIMAL(15,2),
quantity INT,
gross_amount DECIMAL(15,2),
commission DECIMAL(10,2),
tax DECIMAL(10,2),
net_amount DECIMAL(15,2),
trade_date DATE,
settlement_date DATE,
trade_status VARCHAR(20),
exchange_code VARCHAR(20),
broker_id INT,
trade_reference VARCHAR(30),
remarks VARCHAR(100),
FOREIGN KEY (order_id) REFERENCES Orders(order_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id)
);
GO

CREATE TABLE Holdings
(
holding_id INT PRIMARY KEY,
account_id INT,
user_id INT,
stock_id INT,
company_id INT,
quantity INT,
average_price DECIMAL(15,2),
current_price DECIMAL(15,2),
invested_amount DECIMAL(15,2),
current_value DECIMAL(15,2),
profit_loss DECIMAL(15,2),
profit_percentage DECIMAL(7,2),
purchase_date DATE,
last_updated DATE,
status VARCHAR(20),
broker_id INT,
exchange_code VARCHAR(20),
currency VARCHAR(10),
cost_basis DECIMAL(15,2),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id)
);
GO

CREATE TABLE Portfolios
(
portfolio_id INT PRIMARY KEY,
account_id INT,
user_id INT,
portfolio_name VARCHAR(100),
portfolio_type VARCHAR(30),
initial_value DECIMAL(15,2),
current_value DECIMAL(15,2),
profit_loss DECIMAL(15,2),
risk_level VARCHAR(20),
created_date DATE,
updated_date DATE,
status VARCHAR(20),
description VARCHAR(150),
target_value DECIMAL(15,2),
currency VARCHAR(10),
benchmark VARCHAR(50),
stock_count INT,
broker_id INT,
goal VARCHAR(50),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id)
);
GO

CREATE TABLE Watchlists
(
watchlist_id INT PRIMARY KEY,
user_id INT,
account_id INT,
watchlist_name VARCHAR(100),
description VARCHAR(150),
created_date DATE,
updated_date DATE,
status VARCHAR(20),
alert_enabled BIT,
target_price DECIMAL(15,2),
current_price DECIMAL(15,2),
price_change DECIMAL(15,2),
priority VARCHAR(20),
visibility VARCHAR(20),
category VARCHAR(50),
currency VARCHAR(10),
stock_count INT,
broker_id INT,
last_checked DATE,
remarks VARCHAR(100),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id)
);
GO

CREATE TABLE Watchlist_Stocks
(
watchlist_stock_id INT PRIMARY KEY,
watchlist_id INT,
stock_id INT,
user_id INT,
account_id INT,
company_id INT,
added_date DATE,
target_price DECIMAL(15,2),
current_price DECIMAL(15,2),
price_change DECIMAL(15,2),
percentage_change DECIMAL(7,2),
alert_enabled BIT,
alert_type VARCHAR(30),
status VARCHAR(20),
notes VARCHAR(100),
created_at DATE,
updated_at DATE,
broker_id INT,
exchange_code VARCHAR(20),
priority VARCHAR(20),
FOREIGN KEY (watchlist_id) REFERENCES Watchlists(watchlist_id),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id)
);
GO

CREATE TABLE Transactions
(
transaction_id INT PRIMARY KEY,
account_id INT,
user_id INT,
broker_id INT,
order_id INT,
trade_id INT,
transaction_type VARCHAR(30),
amount DECIMAL(15,2),
currency VARCHAR(10),
transaction_date DATE,
reference_number VARCHAR(30),
payment_method VARCHAR(30),
fee DECIMAL(10,2),
tax DECIMAL(10,2),
net_amount DECIMAL(15,2),
status VARCHAR(20),
description VARCHAR(150),
portfolio_id INT,
source VARCHAR(50),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (order_id) REFERENCES Orders(order_id),
FOREIGN KEY (trade_id) REFERENCES Trades(trade_id),
FOREIGN KEY (portfolio_id) REFERENCES Portfolios(portfolio_id)
);
GO

CREATE TABLE Deposits
(
deposit_id INT PRIMARY KEY,
account_id INT,
user_id INT,
broker_id INT,
amount DECIMAL(15,2),
currency VARCHAR(10),
deposit_method VARCHAR(30),
reference_number VARCHAR(30),
deposit_date DATE,
processed_date DATE,
status VARCHAR(20),
fee DECIMAL(10,2),
tax DECIMAL(10,2),
net_amount DECIMAL(15,2),
bank_name VARCHAR(100),
payment_gateway VARCHAR(100),
bank_account_number VARCHAR(30),
branch VARCHAR(50),
city VARCHAR(50),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id)
);
GO

CREATE TABLE Withdrawals
(
withdrawal_id INT PRIMARY KEY,
account_id INT,
user_id INT,
broker_id INT,
amount DECIMAL(15,2),
currency VARCHAR(10),
withdrawal_method VARCHAR(30),
reference_number VARCHAR(30),
withdrawal_date DATE,
processed_date DATE,
status VARCHAR(20),
fee DECIMAL(10,2),
tax DECIMAL(10,2),
net_amount DECIMAL(15,2),
bank_name VARCHAR(100),
bank_account_number VARCHAR(30),
payment_gateway VARCHAR(100),
branch VARCHAR(50),
city VARCHAR(50),
remarks VARCHAR(100),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id)
);
GO

CREATE TABLE Dividends
(
dividend_id INT PRIMARY KEY,
stock_id INT,
company_id INT,
user_id INT,
account_id INT,
dividend_amount DECIMAL(15,2),
dividend_per_share DECIMAL(15,4),
ex_dividend_date DATE,
record_date DATE,
payment_date DATE,
currency VARCHAR(10),
dividend_type VARCHAR(30),
tax_amount DECIMAL(10,2),
net_dividend DECIMAL(15,2),
status VARCHAR(20),
broker_id INT,
portfolio_id INT,
exchange_code VARCHAR(20),
dividend_rate DECIMAL(7,4),
remarks VARCHAR(100),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id)
);
GO

CREATE TABLE Notifications
(
notification_id INT PRIMARY KEY,
user_id INT,
account_id INT,
broker_id INT,
notification_type VARCHAR(30),
title VARCHAR(100),
message VARCHAR(200),
created_at DATE,
read_at DATE,
status VARCHAR(20),
priority VARCHAR(20),
channel VARCHAR(20),
sent_at DATE,
expiry_date DATE,
reference_id INT,
action_url VARCHAR(100),
category VARCHAR(50),
language VARCHAR(30),
sender VARCHAR(50),
remarks VARCHAR(100),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id)
);
GO

CREATE TABLE Alerts
(
alert_id INT PRIMARY KEY,
user_id INT,
account_id INT,
stock_id INT,
company_id INT,
exchange_id INT,
sector_id INT,
broker_id INT,
portfolio_id INT,
watchlist_id INT,
alert_type VARCHAR(30),
target_price DECIMAL(15,2),
current_price DECIMAL(15,2),
condition_type VARCHAR(20),
percentage_threshold DECIMAL(7,2),
message VARCHAR(200),
created_date DATE,
triggered_date DATE,
status VARCHAR(20),
remarks VARCHAR(100),
FOREIGN KEY (user_id) REFERENCES Users(user_id),
FOREIGN KEY (account_id) REFERENCES Accounts(account_id),
FOREIGN KEY (stock_id) REFERENCES Stocks(stock_id),
FOREIGN KEY (company_id) REFERENCES Companies(company_id),
FOREIGN KEY (exchange_id) REFERENCES Exchanges(exchange_id),
FOREIGN KEY (sector_id) REFERENCES Market_Sectors(sector_id),
FOREIGN KEY (portfolio_id) REFERENCES Portfolios(portfolio_id),
FOREIGN KEY (watchlist_id) REFERENCES Watchlists(watchlist_id)
);
GO

