/* Check number of records in every table */
SELECT 'Users' AS table_name, COUNT(*) AS records FROM Users
UNION ALL SELECT 'Accounts', COUNT(*) FROM Accounts
UNION ALL SELECT 'KYC', COUNT(*) FROM KYC
UNION ALL SELECT 'Brokers', COUNT(*) FROM Brokers
UNION ALL SELECT 'Market_Sectors', COUNT(*) FROM Market_Sectors
UNION ALL SELECT 'Companies', COUNT(*) FROM Companies
UNION ALL SELECT 'Exchanges', COUNT(*) FROM Exchanges
UNION ALL SELECT 'Stocks', COUNT(*) FROM Stocks
UNION ALL SELECT 'Stock_Price_History', COUNT(*) FROM Stock_Price_History
UNION ALL SELECT 'Orders', COUNT(*) FROM Orders
UNION ALL SELECT 'Trades', COUNT(*) FROM Trades
UNION ALL SELECT 'Holdings', COUNT(*) FROM Holdings
UNION ALL SELECT 'Portfolios', COUNT(*) FROM Portfolios
UNION ALL SELECT 'Watchlists', COUNT(*) FROM Watchlists
UNION ALL SELECT 'Watchlist_Stocks', COUNT(*) FROM Watchlist_Stocks
UNION ALL SELECT 'Transactions', COUNT(*) FROM Transactions
UNION ALL SELECT 'Deposits', COUNT(*) FROM Deposits
UNION ALL SELECT 'Withdrawals', COUNT(*) FROM Withdrawals
UNION ALL SELECT 'Dividends', COUNT(*) FROM Dividends
UNION ALL SELECT 'Notifications', COUNT(*) FROM Notifications
UNION ALL SELECT 'Alerts', COUNT(*) FROM Alerts
ORDER BY table_name;
GO

/* Check columns in every table */
SELECT TABLE_NAME, COUNT(*) AS total_columns
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_NAME IN
(
'Users','Accounts','KYC','Brokers','Market_Sectors','Companies','Exchanges',
'Stocks','Stock_Price_History','Orders','Trades','Holdings','Portfolios',
'Watchlists','Watchlist_Stocks','Transactions','Deposits','Withdrawals',
'Dividends','Notifications','Alerts'
)
GROUP BY TABLE_NAME
ORDER BY TABLE_NAME;
GO
